 "Prepare Sample Spreadsheet Data2": "const source=$('Prepare ICP Validation2').first().json;const result=$('Calculate Company Fit Gate2').first().json;const leadList=$('Normalize Lead List2').first().json;const parseSheetId=url=>String(url??'').match(/\\/spreadsheets\\/d\\/([a-zA-Z0-9-_]+)/)?.[1]??'';const sheetId=parseSheetId(leadList.sheetLink);return [{json:{recordId:result.recordId,title:leadList.leadListName||('Lead List '+result.recordId),sheetId,hasSheet:Boolean(sheetId),rawRows:source.sourceRows??[],reviewRows:result.reviewed??[]}}];",
 "Prepare Sample Sheet Chunks2": "const data=$('Prepare Sample Spreadsheet Data2').first().json;const safe=value=>value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):value;const output=[];for(const [tab,rows] of [['Raw Companies',data.rawRows],['AI Company Review',data.reviewRows]]){const headers=[...new Set(rows.flatMap(row=>Object.keys(row??{})))];if(!headers.length)continue;const values=[headers,...rows.map(row=>headers.map(header=>safe(row?.[header])))];for(let start=0;start<values.length;start+=500){const range=\"'\"+tab+\"'!A\"+(start+1);output.push({json:{range,encodedRange:encodeURIComponent(range),values:values.slice(start,start+500)}});}}if(!output.length)throw new Error('No sample company rows were available for Google Sheets.');return output;",
